"""Owner-only editor for provider-independent, isolated code execution.

The page never executes user code in the browser or presents generated code as
a deployed change. HTTP authorization and process isolation belong to the API.
"""


def code_execution_workspace_html() -> str:
    """Return the common owner coding workspace; rendering performs no calls."""
    return _HTML


